    20 | pub fn encode(msg: &Msg) -> String {
    21 |     match msg {
    22 |         Msg::Ping => "ping".into(),
    23 |         Msg::Hello(name) => format!("v:2|hello:{}", name),
    24 |         Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{}", sequence),
    25 |     }
    26 | }
    27 | 
    28 | pub fn ping_roundtrip() -> Result<Msg, String> {
    29 |     decode(&encode(&Msg::Ping))
    30 | }
